import random
from pwn import remote

HOST = 'mandf.csaw.io'
PORT = 3000

strategies = {
    'all_zeros': [0]*30,
    'all_ones': [1]*30,
    'inc_seq': list(range(1,31)),
    'random': [random.randint(0, 999) for _ in range(30)]
}

results = {}

for name, vals in strategies.items():
    conn = remote(HOST, PORT)
    received = b''
    try:
        # Read the intro and/or prompts
        for _ in range(3):
            r = conn.recv(timeout=2)
            if not r:
                break
            received += r
        response_log = received.decode(errors='ignore')
        # Send each value, log responses
        for i, v in enumerate(vals):
            conn.sendline(str(v).encode())
            resp = conn.recv(timeout=1)
            if resp:
                response_log += f"[input {i+1}: {v}] " + resp.decode(errors='ignore')
            else:
                response_log += f"[input {i+1}: {v}] <no_response>\n"
        # Log remaining output if any
        try:
            extra = conn.recvall(timeout=2)
            response_log += extra.decode(errors='ignore')
        except Exception:
            pass
        results[name] = response_log
    finally:
        conn.close()

with open("/home/ctfplayer/ctf_files/sigma_probe_results.txt", "w") as f:
    for name, log in results.items():
        f.write(f"== {name} ==\n{log}\n\n")

